SELECT event_type, MONTH(event_time) AS event_month, ROUND(STDDEV(duration_sec), 2) AS stddev_duration_sec, ROUND((100 * SUM(CASE WHEN event_type = 'add_to_cart' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_add_to_cart FROM web_events WHERE session_id = 1 AND (session_id IN (14, 24) OR duration_sec >= 429) GROUP BY event_type, MONTH(event_time) ORDER BY pct_add_to_cart, event_type, event_month LIMIT 5;
